CREATE TABLE "notification_event_settings" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL REFERENCES "users" ("id"),
    "type" VARCHAR(30) NOT NULL,
    "enabled" BOOLEAN NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_notification_event_settings_user_id_type" UNIQUE ("user_id", "type")
);

CREATE INDEX "idx_notification_event_settings_type_enabled_user_id"
    ON "notification_event_settings" ("type", "enabled", "user_id");

INSERT INTO "notification_event_settings" ("user_id", "type", "enabled", "created_at", "updated_at")
SELECT DISTINCT d."user_id", t."type", TRUE, NOW(), NOW()
FROM "device_installations" d
CROSS JOIN (VALUES ('AI_ANALYSIS'), ('OPERATOR_MESSAGE'), ('COMMENT')) AS t("type");
